// C++98 / C++03: base historica. Templates, STL, exceptions, RTTI.

// C++11 (2011): onde C++ moderno comeca
// - auto, range-based for, nullptr
// - lambdas, std::function
// - rvalue references + move semantics
// - smart pointers (unique_ptr, shared_ptr, weak_ptr)
// - std::thread, std::mutex, std::atomic
// - variadic templates, constexpr (basico)

// C++14: refinamentos
// - generic lambdas (auto parametros)
// - return type deduction em funcoes
// - std::make_unique

// C++17: moderno pragmatico
// - structured bindings: auto [k, v] = pair;
// - if constexpr (template branching)
// - std::optional, std::variant, std::any
// - std::filesystem
// - CTAD (class template argument deduction)

// C++20: salto maior desde C++11
// - concepts (substitui SFINAE): template<typename T> requires ...
// - ranges: views::filter | views::transform | views::take
// - modules: import std; (substitui #include)
// - coroutines: co_await, co_yield, co_return
// - std::format (substitui printf/cout)
// - three-way comparison: operator<=> (spaceship)

// C++23: refinamentos de C++20
// - std::expected<T, E> (alternativa a exceptions)
// - std::print / std::println (ergonomia)
// - deducing this (explicit object parameter)
// - std::flat_map, std::mdspan

// 1. RAII: destrutores deterministicos
// Recurso eh liberado quando o objeto sai de escopo — sem GC, sem finalize.
{
    std::lock_guard<std::mutex> lock(m);  // trava aqui
    std::ofstream f("log.txt");           // abre arquivo
    // ... trabalho ...
}  // destrutores rodam em ordem reversa: fecha arquivo, libera mutex

// 2. Templates monomorfizados: generic sem virtual call
// std::sort com lambda inlina comparador — codigo assembly identico
// ao loop manual. Sem interface dispatch, sem boxing.
std::ranges::sort(v, [](auto a, auto b) { return a.price < b.price; });

// 3. Controle total de layout de memoria
// struct packing, alignas, SIMD intrinsics, allocators custom.
// Usado em game engines (ECS), trading (cache lines), ML (SIMD kernels).
alignas(64) struct HotData { /* fits in single cache line */ };
